// Un solo modelo para todos: un único "Pedido" con un único "estado".
const ESTADOS = ['confirmado', 'armado', 'en_ruta', 'entregado', 'facturado'];

function crearPedido(id, lineas) {
  return { id, estado: 'confirmado', lineas, bultosDespachados: 0 };
}

// Regla de Ventas: un pedido facturado no se modifica.
function modificarLineas(p, nuevas) {
  if (p.estado === 'facturado') throw new Error('Pedido facturado: no se modifica');
  return { ...p, lineas: nuevas };
}

// Regla de Depósito: se despacha por partes. Cuando salió el primer bulto, el pedido "está en ruta".
function despacharBulto(p, totalBultos) {
  const bultosDespachados = p.bultosDespachados + 1;
  return { ...p, bultosDespachados, estado: 'en_ruta' };
}

let p = crearPedido('P-1', [{ sku: 'AGUA-6L', cant: 3 }]);
p = despacharBulto(p, 3);            // sale 1 de 3 bultos
console.log('Depósito:', p.estado, p.bultosDespachados + '/3');
p.estado = 'facturado';              // Ventas factura apenas sale el primero (así lo hace su proceso)
console.log('Ventas:', p.estado);
try { modificarLineas(p, [{ sku: 'AGUA-6L', cant: 2 }]); } catch (e) { console.log('Error:', e.message); }
// Y ahora, ¿cómo sale el segundo bulto? Despacho lo pasa a 'en_ruta' y pisa la factura:
p = despacharBulto(p, 3);
console.log('Después del 2.º bulto:', p.estado, '<- se perdió que estaba facturado');

// Antes: el código habla en un idioma que nadie en el depósito usa.
function proc(o, n) {
  o.st = n === o.t ? 3 : 2;
  return o;
}

// Después: los nombres son los de la gente que lo usa.
function registrarBultoSalido(orden) {
  const bultosSalidos = orden.bultosSalidos + 1;
  const estado = bultosSalidos === orden.bultosTotal ? 'completa' : 'parcial';
  return { ...orden, bultosSalidos, estado };
}

let orden = { id: 'OP-P-1', bultosTotal: 3, bultosSalidos: 0, estado: 'pendiente' };
orden = registrarBultoSalido(orden);
console.log(orden.estado, orden.bultosSalidos + '/' + orden.bultosTotal);
orden = registrarBultoSalido(registrarBultoSalido(orden));
console.log(orden.estado, orden.bultosSalidos + '/' + orden.bultosTotal);

// Tres contextos, tres modelos. Cada uno dice "pedido" a su manera.
const Ventas = {
  nuevoPedido: (id, cliente, lineas, condicion) => ({ id, cliente, lineas, condicion, estado: 'confirmado' }),
  total: (p) => p.lineas.reduce((s, l) => s + l.cant * l.precioCents, 0),
  facturar: (p) => ({ ...p, estado: 'facturado' }),
};

const Deposito = {
  // Para el depósito, lo que existe es una orden de picking, con bultos y pesos.
  ordenDePicking: (id, ref, lineas) => ({ id, ref, lineas, bultosTotal: 0, bultosSalidos: 0 }),
  pesoKg: (o, pesoPorSku) => o.lineas.reduce((s, l) => s + l.cant * pesoPorSku[l.sku], 0),
  salioBulto: (o) => ({ ...o, bultosSalidos: o.bultosSalidos + 1 }),
  completa: (o) => o.bultosSalidos === o.bultosTotal,
};

const Transporte = {
  // Para el transporte no hay pedidos: hay paradas en una hoja de ruta.
  parada: (id, direccion, ventana, bultos) => ({ id, direccion, ventana, bultos, estado: 'pendiente' }),
};

// Traductores en la frontera entre contextos: cada uno conoce los dos idiomas.
function ventasADeposito(pedido, bultos) {
  return { ...Deposito.ordenDePicking('OP-' + pedido.id, pedido.id, pedido.lineas.map(({ sku, cant }) => ({ sku, cant }))), bultosTotal: bultos };
}
function depositoATransporte(orden, direccion, ventana) {
  return Transporte.parada('PA-' + orden.ref, direccion, ventana, orden.bultosTotal);
}

const pesoPorSku = { 'AGUA-6L': 6.3, 'FIDEOS-1K': 1.0 };
let pv = Ventas.nuevoPedido('P-1', 'Kiosco Norte', [{ sku: 'AGUA-6L', cant: 3, precioCents: 240000 }, { sku: 'FIDEOS-1K', cant: 10, precioCents: 95000 }], '30 días');
let op = ventasADeposito(pv, 3);
console.log('Ventas: total en centavos =', Ventas.total(pv));
console.log('Depósito: peso =', Deposito.pesoKg(op, pesoPorSku).toFixed(1), 'kg en', op.bultosTotal, 'bultos');

pv = Ventas.facturar(pv);                 // Ventas factura cuando quiere
op = Deposito.salioBulto(op);              // Depósito despacha cuando puede
console.log('Ventas:', pv.estado, '| Depósito:', op.bultosSalidos + '/' + op.bultosTotal, '| completa:', Deposito.completa(op));
op = Deposito.salioBulto(Deposito.salioBulto(op));
console.log('Depósito después:', op.bultosSalidos + '/' + op.bultosTotal, '| completa:', Deposito.completa(op));
console.log('Transporte:', JSON.stringify(depositoATransporte(op, 'Av. Corrientes 1234', '9-12')));
console.log('Ventas sigue en:', pv.estado);
